/** A real oneof whose name starts with underscore and has exactly one field. The Go plugin may misidentify this as a proto3 optional field because: - oneof name starts with "_" - oneof has exactly 1 fiel… */
export interface Container {
    name: string;
    Value: {
        oneofKind: "value";
        value: string;
    } | {
        oneofKind: undefined;
    };
}
